//! Ordered reports over the SAME retained global summary and bounded PAGE loans.
use super::*;
use dm_analysis::checker_effects::{EffectSource,EffectReportPhase};
use std::{cell::RefCell,ops::Deref};
pub(super) const PURE:Kind=Kind(26);pub(super) const SLEEP:Kind=Kind(27);
pub(super) struct ReportData{rows:Vec<Produced>,input:Weak<EffectInput>,phase:EffectReportPhase,width:usize,start:usize,count:usize,total:usize,policy:u128,#[cfg(test)]work_counts:(usize,usize,usize)}
pub(crate) struct NativeEffectReport{payload:Option<Arc<ReportPayload>>}
struct ReportPayload{data:ReportData,lease:graph_work::GraphLease,#[cfg(test)]drop_pause:Mutex<Option<(Arc<std::sync::Barrier>,Arc<std::sync::Barrier>)>>}
impl Drop for NativeEffectReport{fn drop(&mut self){if let Some(payload)=self.payload.take().and_then(Arc::into_inner){#[cfg(test)]if let Some((entered,release))=payload.drop_pause.lock().unwrap_or_else(|e|e.into_inner()).take(){entered.wait();release.wait();}let ReportPayload{data,lease,..}=payload;drop(data);drop(lease);}}}
impl Deref for NativeEffectReport{type Target=Vec<Produced>;fn deref(&self)->&Vec<Produced>{&self.payload().data.rows}}
impl NativeEffectReport{
 #[cfg(test)]pub(crate) fn report_scope_counts(&self)->(usize,usize,usize){self.payload().data.work_counts}
 fn payload(&self)->&ReportPayload{self.payload.as_deref().expect("sealed original effect report")}
 pub(super) fn validate(&self,input:&Arc<EffectInput>,phase:EffectReportPhase,width:usize,start:usize,count:usize,total:usize,policy:u128)->Result<(),String>{let data=&self.payload().data;if !data.input.ptr_eq(&Arc::downgrade(input))||data.phase!=phase||data.width!=width||data.start!=start||data.count!=count||data.total!=total||data.policy!=policy{return Err("effect report belongs to another original source/request".into())}Ok(())}
 pub(crate) fn retained_charge(&self)->Option<usize>{dm_analysis::checker_effects::report_capacity_bound(&self.payload().data.rows).checked_add(std::mem::size_of::<EffectInput>().checked_add(2*std::mem::size_of::<usize>())?)?.checked_add(Self::coordination_charge())}
 fn coordination_charge()->usize{std::mem::size_of::<ReportPayload>().saturating_sub(std::mem::size_of::<Vec<Produced>>())}
 pub(crate) fn visit_storage(&self,mut visit:impl FnMut(Storage)){let payload=self.payload();dm_analysis::checker_effects::visit_report(&payload.data.rows,&mut visit);visit(Storage::Buffer{owner:"purity.original_report_payload",address:payload as *const ReportPayload as usize,logical:std::mem::size_of::<ReportPayload>(),capacity:std::mem::size_of::<ReportPayload>()});visit(Storage::Buffer{owner:"purity.original_report_input_weak",address:payload.data.input.as_ptr() as usize,logical:std::mem::size_of::<EffectInput>(),capacity:std::mem::size_of::<EffectInput>()});visit(Storage::Buffer{owner:"purity.original_report_completion",address:Arc::as_ptr(&payload.lease.completion) as usize,logical:std::mem::size_of::<std::sync::atomic::AtomicBool>(),capacity:std::mem::size_of::<std::sync::atomic::AtomicBool>()});}
 #[cfg(test)]pub(crate) fn pause_drop_for_test(&self,entered:Arc<std::sync::Barrier>,release:Arc<std::sync::Barrier>){*self.payload().drop_pause.lock().unwrap_or_else(|e|e.into_inner())=Some((entered,release));}
}
impl graph_work::RetainedHandle for NativeEffectReport{fn fingerprint(&self,_:Key)->u128{let data=&self.payload().data;let mut hash=xxhash_rust::xxh3::Xxh3::new();hash.update(b"original-ordered-effect-report-v1");hash.update(&dm_analysis::checker_effects::report_fingerprint(&data.rows).to_le_bytes());hash.update(&data.width.to_le_bytes());hash.update(&data.start.to_le_bytes());hash.update(&data.count.to_le_bytes());hash.update(&data.total.to_le_bytes());hash.update(&data.policy.to_le_bytes());hash.update(&[match data.phase{EffectReportPhase::Purity=>0,EffectReportPhase::Sleep=>1}]);hash.digest128()}type Data=ReportData;fn coordination_charge()->usize{Self::coordination_charge()}fn issue(data:ReportData,ledger:Arc<Mutex<Ledger>>,completion:Arc<std::sync::atomic::AtomicBool>)->Arc<Self>{Arc::new(Self{payload:Some(Arc::new(ReportPayload{data,lease:graph_work::GraphLease::new(ledger, completion),#[cfg(test)]drop_pause:Mutex::new(None)}))})}fn retained_charge(&self)->Option<usize>{Self::retained_charge(self)}}
struct ReportParams{base:Params,width:usize,start:usize,count:usize,total:usize,phase:EffectReportPhase,policy_key:u128,old_edges:usize,dependencies:std::sync::atomic::AtomicUsize}
pub(super) fn report_key(input:&EffectInput,width:usize,phase:EffectReportPhase,policy:u128,start:usize,count:usize)->Key{let kind=match phase{EffectReportPhase::Purity=>PURE,EffectReportPhase::Sleep=>SLEEP};let mut hash=xxhash_rust::xxh3::Xxh3::new();hash.update(&width.to_le_bytes());hash.update(&policy.to_le_bytes());hash.update(&start.to_le_bytes());hash.update(&count.to_le_bytes());key(kind,input,hash.digest128())}
fn finish_source_error(ledger:&Arc<Mutex<Ledger>>,key:Key,message:String)->Result<Outcome,QueryError>{let bytes=message.capacity();finish_using::<NativeEffectReport>(ledger,key,Err(message),bytes,pages::typed_publication,|key,actual|QueryError::operational(key,std::io::Error::new(std::io::ErrorKind::OutOfMemory,actual)))}
fn transport(ledger:&Arc<Mutex<Ledger>>,error:ReadFailure)->dm_analysis::policy_body_demand::PolicyFailure{match error{ReadFailure::Semantic(message)=>message.into(),ReadFailure::Query(error)=>dm_analysis::policy_body_demand::PolicyFailure::Operational(pages::restore_graph_error(ledger,error))}}

pub(super) fn register(db:&Db,ledger:Arc<Mutex<Ledger>>,registry:SourceRegistry){for kind in [PURE,SLEEP]{let ledger=ledger.clone();let registry=registry.clone();db.define(kind,"native-original-ordered-global-effect-report",move|ctx,raw|{
 let p=raw.downcast_ref::<ReportParams>().expect("original report params");let produced=(||{let k=p.base.key;pages::typed_publication(&ledger,k)?;let input=p.base.input.upgrade().ok_or(QueryError::Missing(k))?;let policy=p.base.policy.upgrade().ok_or(QueryError::Missing(k))?;match checked_sources_using::<ReadFailure>(&input,&p.base.sources,&registry,||crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(k,actual)))){Ok(())=>(),Err(ReadFailure::Query(actual))=>return Err(actual),Err(ReadFailure::Semantic(message))=>return finish_source_error(&ledger,k,message)};
 let summary=match global_summary::obtain(ctx,&ledger,&input,&p.base.sources,p.width){Ok(value)=>value,Err(ReadFailure::Query(actual))=>return Err(actual),Err(ReadFailure::Semantic(message))=>{let bytes=message.capacity();return finish_using::<NativeEffectReport>(&ledger,k,Err(message),bytes,pages::typed_publication,|key,actual|QueryError::operational(key,std::io::Error::new(std::io::ErrorKind::OutOfMemory,actual)))}};
 let source=match EffectSource::new(input.archive(),input.profile()).map_err(|error|policy_read_failure(k,error)){Ok(value)=>value,Err(ReadFailure::Query(actual))=>return Err(actual),Err(ReadFailure::Semantic(message))=>return finish_source_error(&ledger,k,message)};let (facts,graph)=match summary.original_report_inputs(&source).map_err(|error|policy_read_failure(k,error)){Ok(value)=>value,Err(ReadFailure::Query(actual))=>return Err(actual),Err(ReadFailure::Semantic(message))=>return finish_source_error(&ledger,k,message)};let resolver=match input.archive().tree().validated_checker_profile(input.profile()){Ok(value)=>value,Err(error)=>return finish_source_error(&ledger,k,format!("effect report original profile: {error:?}"))};
 let admission=pages::page_execution_admission(&ledger).map_err(|message|QueryError::operational(k,std::io::Error::new(std::io::ErrorKind::OutOfMemory,message)))?;let work=RefCell::new(graph_work::GraphWork::new(ledger.clone(),k));let ctx=RefCell::new(&mut *ctx);let computed=source.report_pages_window_checked(graph,facts,p.start,p.count,p.phase,&resolver,&policy,&admission,&mut crate::daemon::control::checkpoint,|start,width,live|{let mut ctx=ctx.borrow_mut();let child=pages::page_key(&input,start,width);if !ctx.has_dependency(child){pages::reserve_actual_dependency(&ledger,k,p.old_edges,ctx.dependency_count()+1,live,admission.available()).map_err(dm_analysis::policy_body_demand::PolicyFailure::Operational)?;}pages::obtain_retained(&mut **ctx,&ledger,&input,&p.base.sources,start,width).map_err(|error|transport(&ledger,error))},&mut *work.borrow_mut());latch_transient_denial(&ledger,&admission);
 match split_transport(computed.map_err(|error|policy_read_failure(k,error)))?{Ok(rows)=>{match checked_sources_using::<ReadFailure>(&input,&p.base.sources,&registry,||crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(k,actual)))){Ok(())=>(),Err(ReadFailure::Query(actual))=>return Err(actual),Err(ReadFailure::Semantic(message))=>return finish_source_error(&ledger,k,message)};pages::typed_publication(&ledger,k)?;work.borrow_mut().reserve(std::mem::size_of::<EffectInput>().saturating_add(2*std::mem::size_of::<usize>())).map_err(|actual|QueryError::operational(k,actual))?;let data=ReportData{rows,input:Arc::downgrade(&input),phase:p.phase,width:p.width,start:p.start,count:p.count,total:p.total,policy:p.policy_key,#[cfg(test)]work_counts:work.borrow().report_scope_counts()};work.into_inner().publish_data::<NativeEffectReport>(data)},Err(message)=>{let outcome=finish_source_error(&ledger,k,message);drop(work);outcome}}
 })();p.dependencies.store(ctx.dependency_count(),std::sync::atomic::Ordering::Release);produced
 });}}

impl QueryDb{pub(crate) fn native_effect_source_report(&self,input:&Arc<EffectInput>,scope:&crate::runner_host::query_snapshot::PurityScope<'_>,width:usize,phase:EffectReportPhase)->std::io::Result<Arc<NativeEffectReport>>{let total=input.archive().callables().source_order().len();self.native_effect_source_report_window(input,scope,width,phase,0,total)}
 pub(crate) fn native_effect_source_report_window(&self,input:&Arc<EffectInput>,scope:&crate::runner_host::query_snapshot::PurityScope<'_>,width:usize,phase:EffectReportPhase,start:usize,count:usize)->std::io::Result<Arc<NativeEffectReport>>{
 crate::daemon::control::checkpoint()?;scope.validate(self,input).map_err(std::io::Error::other)?;self.prune_purity();let _gate=self.purity.gate.lock().unwrap_or_else(|e|e.into_inner());scope.validate(self,input).map_err(std::io::Error::other)?;{let mut ledger=self.purity.ledger.lock().unwrap_or_else(|e|e.into_inner());ledger.denied=false;ledger.aborted=None;}self.native_effect_source_report_window_locked(input,scope,width,phase,start,count,false)
 }
 /// Caller holds the SAME purity gate for the complete buffered operation.
 pub(super) fn native_effect_source_report_window_locked(&self,input:&Arc<EffectInput>,scope:&crate::runner_host::query_snapshot::PurityScope<'_>,width:usize,phase:EffectReportPhase,start:usize,count:usize,retire:bool)->std::io::Result<Arc<NativeEffectReport>>{
 crate::daemon::control::checkpoint()?;scope.validate(self,input).map_err(std::io::Error::other)?;let result=(||->Result<Arc<NativeEffectReport>,ReadFailure>{let total=input.archive().callables().source_order().len();if !input.is_source_page_context()||width==0||width>dm_analysis::checker_effects::MAX_EVENTS||count>dm_analysis::checker_effects::MAX_EVENTS||start>total||count>total-start{return Err("effect source report requires original page context/window".into())}let k=report_key(input,width,phase,scope.policy_key(),start,count);let sources=self.purity_sources_using::<ReadFailure>(input,|keys|checked_sources_using::<ReadFailure>(input,keys,&self.sources,||crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(k,actual)))),|actual|ReadFailure::Query(QueryError::operational(k,std::io::Error::new(std::io::ErrorKind::OutOfMemory,actual))))?;let size=policy_charge(scope.policy());{let mut ledger=self.purity.ledger.lock().unwrap_or_else(|e|e.into_inner());ledger.admit(size)?;ledger.active_policy=size;}let _policy_work=PolicyWorkingSet{ledger:self.purity.ledger.clone()};let policy=Arc::new(scope.policy().clone());let _node=node_admission(&self.purity.ledger,input,k,std::mem::size_of::<ReportParams>())?;let mut dependencies=pages::reserve_dependencies(&self.purity.ledger,k,1)?;let params=Arc::new(ReportParams{base:Params{body_admission:None,input:Arc::downgrade(input),key:k,ordinal:0,sources,policy:Arc::downgrade(&policy)},width,start,count,total,phase,policy_key:scope.policy_key(),old_edges:dependencies.old,dependencies:std::sync::atomic::AtomicUsize::new(0)});remember_params(&self.purity.ledger,input,k,&params);let result=self.db.get::<Result<Arc<NativeEffectReport>,String>>(k,params.clone()).map_err(ReadFailure::Query)?;dependencies.commit(params.dependencies.load(std::sync::atomic::Ordering::Acquire));let value=result.as_ref().clone().map_err(ReadFailure::Semantic)?;crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(k,actual)))?;scope.validate(self,input)?;value.validate(input,phase,width,start,count,total,scope.policy_key())?;if retire{self.db.evict_value_if_current(k,&result);}Ok(value)})();
 match result{Err(ReadFailure::Query(actual))=>Err(pages::restore_graph_error(&self.purity.ledger,actual)),other=>{crate::daemon::control::checkpoint()?;if self.purity.ledger.lock().unwrap_or_else(|e|e.into_inner()).denied{return Err(std::io::Error::new(std::io::ErrorKind::OutOfMemory,"native original effect report admission exhausted"))}match other{Ok(value)=>Ok(value),Err(ReadFailure::Semantic(message))=>Err(std::io::Error::other(message)),Err(ReadFailure::Query(_))=>unreachable!()}}}
}}
